import React from 'react';
import './Dashboard.css';
import TabNavigation from './TabNavigation';
import EquipeSection from './EquipeSection';
import VehiculesSection from './VehiculesSection';
import TrajetsSection from './TrajetsSection';
import ContratsSection from './ContratsSection';
import HistoriqueSection from './HistoriqueSection';
import NotificationsSection from './NotificationsSection';

const Dashboard = ({ activeTab, setActiveTab }) => {
  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h1>Entreprise</h1>
        <TabNavigation activeTab={activeTab} setActiveTab={setActiveTab} />
      </div>
      
      <div className="dashboard-content">
        <div className="left-column">
          <EquipeSection />
          <VehiculesSection />
          <TrajetsSection />
        </div>
        
        <div className="right-column">
          <ContratsSection />
          <HistoriqueSection />
          <NotificationsSection />
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
